import{_ as t,o as a,c as n,a4 as r}from"./chunks/framework.CzJ_HCFe.js";const m=JSON.parse('{"title":"Panchangam Provenance Disclosure","description":"","frontmatter":{},"headers":[],"relativePath":"reference/46-panchangam-provenance-disclosure.md","filePath":"reference/46-panchangam-provenance-disclosure.md","lastUpdated":1788237817000}'),d={name:"reference/46-panchangam-provenance-disclosure.md"};function i(o,e,s,c,l,h){return a(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="panchangam-provenance-disclosure" tabindex="-1">Panchangam Provenance Disclosure <a class="header-anchor" href="#panchangam-provenance-disclosure" aria-label="Permalink to &quot;Panchangam Provenance Disclosure&quot;">​</a></h1><p>The daily Panchangam mixes astronomical events, calendar conventions, traditional time windows, festival rules and derived classifications. A green calculation test for one layer cannot grant authority to the others.</p><p><code>tool_get_panchangam</code>, <code>tool_get_panchangam_range</code> and the compact <code>tool_get_muhurta</code> therefore return a <code>provenance</code> object whose <code>coverage_groups</code> cover every non-identity output category. Each group names a ledger claim, its current state and a plain-language limitation.</p><h2 id="current-evidence-map" tabindex="-1">Current evidence map <a class="header-anchor" href="#current-evidence-map" aria-label="Permalink to &quot;Current evidence map&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Group</th><th>Drik state</th><th>Surya Siddhanta / Vakya state</th><th>Main limitation</th></tr></thead><tbody><tr><td>Pancha Anga and sky events</td><td>Partially verified</td><td>Engine-pinned</td><td>Representative comparisons are not exhaustive; non-Drik systems lack an external fixture</td></tr><tr><td>Calendar metadata</td><td>Needs locator</td><td>Needs locator</td><td>Naming and rollover conventions need criterion-level and regional sources</td></tr><tr><td>Mixed daily windows</td><td>Partially verified</td><td>Partially verified</td><td>Varjyam and Durmuhurtham have inspected passages; several regional component tables still need criterion-level evidence</td></tr><tr><td>Bhadra Mukha / Puchha</td><td>Verified</td><td>Verified</td><td>Muhurta Chintamani 44 supplies the Tithi-specific quarters and nominal widths</td></tr><tr><td>Sankramana avoidance</td><td>Verified</td><td>Verified</td><td>Raman explicitly rejects 16 Ghatis on either side of solar ingress</td></tr><tr><td>Festivals and special-day labels</td><td>Partially verified</td><td>Partially verified</td><td>The forward fixture has 1 independently checked cell and 29 engine-pinned cells</td></tr><tr><td>Eclipse events</td><td>Engine-pinned</td><td>Engine-pinned</td><td>No independent event-by-event comparison fixture is registered</td></tr><tr><td>Panchaka Rahita</td><td>Verified</td><td>Verified</td><td>Raman supplies the four-factor modulo-nine rule, result names and activity exceptions</td></tr><tr><td>Other derived classifications</td><td>Needs locator</td><td>Needs locator</td><td>Each Yoga, Dosha and classification needs its own table crosswalk</td></tr></tbody></table><h2 id="why-this-matters" tabindex="-1">Why this matters <a class="header-anchor" href="#why-this-matters" aria-label="Permalink to &quot;Why this matters&quot;">​</a></h2><p>“Computed” means that an engine produced a value. “Engine-pinned” means tests will detect output drift. Neither means a traditional interpretation has an inspected scriptural locator, nor that an external Panchangam agrees for all locations and dates. Consumers can now preserve those distinctions instead of presenting the whole response as uniformly verified.</p><h2 id="enforcement" tabindex="-1">Enforcement <a class="header-anchor" href="#enforcement" aria-label="Permalink to &quot;Enforcement&quot;">​</a></h2><p>Tests flatten <code>coverage_groups.fields</code> and require exact coverage of every non-identity response key. They also resolve every <code>claim_id</code> against <code>provenance.json</code> and require the declared state to match the ledger. Adding a new Panchangam response category without assigning an evidence state fails the contract test.</p><p>The remaining evidence work should resolve one component at a time, starting with calendar semantics and the high-visibility Rahu Kalam, Gulika, Yamagandam and Choghadiya tables. A mixed response container remains only <code>partially_verified</code> until every component is independently supported; an inspected passage for one member never upgrades the whole bundle.</p>',10)])])}const u=t(d,[["render",i]]);export{m as __pageData,u as default};
